use std::{collections::HashMap,fs};
use gml_parser::ast::{AST,Expr};

fn value(expr:&Expr, vars:&HashMap<Vec<u8>,String>) -> Result<String,String> {
    match expr {
        Expr::LiteralString(s)=>String::from_utf8(s.to_vec()).map_err(|e|e.to_string()),
        Expr::LiteralIdentifier(name)=>vars.get(*name).cloned().ok_or_else(||"Unbound variable".to_string()),
        Expr::Binary(b) if b.op.to_string()=="+" => Ok(value(&b.left,vars)?+&value(&b.right,vars)?),
        _=>Err(format!("Unsupported expression {expr:?}")),
    }
}
fn main() -> Result<(),String> {
    let source=fs::read("hello.gml").map_err(|e|e.to_string())?;
    let entries=AST::new(&source).map_err(|e|e.to_string())?;
    let mut vars=HashMap::new();
    let mut output=Vec::new();
    for entry in entries {
        match entry {
            Expr::Var(v)=> {
                for name in v.vars { vars.insert(name.to_vec(),String::new()); }
            },
            Expr::Binary(b) if b.op.to_string()=="=" => {
                if let Expr::LiteralIdentifier(name)=b.left {
                    if !vars.contains_key(name) {return Err("Assignment to unknown variable".to_string());}
                    vars.insert(name.to_vec(),value(&b.right,&vars)?);
                } else {return Err("Invalid assignment target".to_string());}
            },
            Expr::Function(call) if call.name==b"show_debug_message" && call.params.len()==1 => {
                output.push(value(&call.params[0],&vars)?);
            },
            other=>return Err(format!("Unsupported statement {other:?}")),
        }
    }
    if output.len()!=1 {return Err("Missing or duplicate debug event".to_string());}
    println!("{}", output[0]);
    Ok(())
}
